use vstd::prelude::*;
use vstd::vec::*;

verus! {

// Specification function: true if k exists in arr
spec fn spec_contains(arr: Seq<i32>, k: i32) -> bool {
    exists|i: int| 0 <= i < arr.len() && arr[i] == k
}

fn contains_k(arr: &Vec<i32>, k: i32) -> (result: bool)
    ensures
        result == spec_contains(arr.view(), k),
{
    let mut i: usize = 0;
    let mut found: bool = false;
    
    while i < arr.len()
        invariant
            0 <= i <= arr.len(),
            found == spec_contains(arr.view().subrange(0, i as int), k),
        decreases arr.len() - i,
    {
        if arr[i] == k {
            found = true;
        }
        i = i + 1;
    }
    
    // Postcondition proof
    proof {
        // The entire array is arr[0..arr.len()]
        // Our invariant ensures found == true iff k exists in arr[0..i]
        // When loop ends, i == arr.len(), so arr[0..i] is the entire array
        assert(found == spec_contains(arr.view(), k));
    }
    
    found
}

} // verus!

